rule.example:
// Bad - both shapes read the JVM default zone
LocalDateTime created = LocalDateTime.now();
Supplier<LocalDateTime> clock = LocalDateTime::now;

// Good
LocalDateTime created = TimeProvider.DEFAULT.now();
LocalDateTime created = LocalDateTime.now(ZoneOffset.UTC);

// Bad - the flag is restored on the IOException arm too
try {
    process.waitFor();
} catch (IOException | InterruptedException e) {
    Thread.currentThread().interrupt();
    return false;
}

// Good - split, so only the InterruptedException arm restores it
try {
    process.waitFor();
} catch (InterruptedException e) {
    Thread.currentThread().interrupt();
    return false;
} catch (IOException e) {
    return false;
}
